parts.text:
[
  {
    "statement": "Two studies reported that setting and enforcing vessel speed limits reduced deaths from collisions.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "A before-and-after study in the Indian River estuarine system (USA) reported fewer manatee deaths after speed limits were set and enforced in all areas.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "A before-and-after study in the North Atlantic Ocean (USA) found fewer North Atlantic right whale deaths during periods with speed limits in key habitats.",
    "citations": [
      "2777"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of diverting shipping routes.",
    "citations": [
      "2754"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of using onboard observers to detect mammals and alter course or speed.",
    "citations": [
      "2755"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of using remote tools to detect mammals and alter course or speed.",
    "citations": [
      "2757"
    ]
  },
  {
    "statement": "The action documents do not report cost or cost-effectiveness data for methods to reduce lethal vessel strikes on large whales.",
    "citations": [
      "2754",
      "2755",
      "2757",
      "2777"
    ]
  }
]

[
  {
    "statement": "No action documents reported evidence on public education campaigns reducing plastic litter ingestion by river dolphins in South America.",
    "citations": []
  },
  {
    "statement": "The available evidence on education for marine and freshwater mammals showed only changes in participant intentions and behaviors.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "Changes in participant intentions and behaviors included an increased willingness to support marine conservation.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "Changes in participant intentions and behaviors included an increased willingness to cut fishing nets to save entangled dolphins in Peru.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "Available evidence on education for marine and freshwater mammals reported no population or health outcomes.",
    "citations": [
      "2935"
    ]
  },
  {
    "statement": "Additional education programme evidence concerned terrestrial carnivores in South Africa.",
    "citations": [
      "2423"
    ]
  },
  {
    "statement": "Additional education programme evidence concerned household outreach on garbage and bears in the USA.",
    "citations": [
      "2423"
    ]
  },
  {
    "statement": "Additional education programme evidence did not concern dolphins or plastic ingestion outcomes.",
    "citations": [
      "2423"
    ]
  },
  {
    "statement": "A review from North America stated education alone was not sufficient to change behavior without complementary measures.",
    "citations": [
      "162"
    ]
  },
  {
    "statement": "The review from North America did not provide outcomes for dolphins or plastic ingestion.",
    "citations": [
      "162"
    ]
  }
]
